var SETTINGS_STORAGE_KEY = 'f2a.panelSettings';
function _hasClientStorage() {
  return typeof figma !== 'undefined' && figma.clientStorage &&
    typeof figma.clientStorage.getAsync === 'function' &&
    typeof figma.clientStorage.setAsync === 'function';
}

figma.ui.onmessage = function (msg) {
  if (typeof F2AMCP !== 'undefined' && F2AMCP.resume(msg)) {
    if (mcpCommandId) figma.ui.postMessage({type:'command_progress', commandId:mcpCommandId});
    return;
  }
  if (msg.type === 'load-settings') {
    if (!_hasClientStorage()) {
      figma.ui.postMessage({ type: 'settings-loaded', settings: null });
      return;
    }
    figma.clientStorage.getAsync(SETTINGS_STORAGE_KEY).then(function (saved) {
      figma.ui.postMessage({ type: 'settings-loaded', settings: saved && typeof saved === 'object' ? saved : null });
    }).catch(function () {
      figma.ui.postMessage({ type: 'settings-loaded', settings: null });
    });
    return;
  }
  if (msg.type === 'save-settings') {
    if (!_hasClientStorage() || !msg.settings || typeof msg.settings !== 'object') return;
    figma.clientStorage.setAsync(SETTINGS_STORAGE_KEY, msg.settings).catch(function () {});
    return;
  }
  if (msg.type === 'mcp-info') {
    reportMcpInfo();
    return;
  }
  if (msg.type === 'mcp-command') return executeMcpCommand(msg);
  if (msg.type === 'locate-layer') return locateErrorLayer(msg.nodeId);
  if (msg.type === 'ship-selection') exportSelectionSVG(!!msg.useNodes, !!msg.organize, msg.ignoreHidden !== false, msg.convertMasks === true, msg.rasterGroups !== false, msg.rasterTexts === true, msg);
  if (msg.type === 'mark-raster') markRasterSelection(true);
  if (msg.type === 'unmark-raster') markRasterSelection(false);
  if (msg.type === 'mark-root') markRootSelection(true);
  if (msg.type === 'unmark-root') markRootSelection(false);
  if (msg.type === 'layer-tool') runLayerTool(msg.action);
  if (msg.type === 'close') figma.closePlugin(msg.message || undefined);
  if (msg.type === 'notify') figma.notify(msg.message);
};

// Tell the UI about selection so the button can enable/disable + show a count.
function reportSelection() {
  var selection = figma.currentPage.selection;
  figma.ui.postMessage({ type: 'selection', count: selection.length,
    workspacePlugin: figma.pluginId === 'f2a-ship-to-ae-workspace',
    frameSelected: selection.some(function (n) { return n.type === 'FRAME'; }) });
}
figma.on('selectionchange', reportSelection);
reportSelection();

// Share the document with the embedded MCP handlers without replacing F2A's UI callbacks.
var mcpQueue = Promise.resolve(), mcpBusy = false, mcpCommandId = null;
function reportMcpInfo() {
  figma.ui.postMessage({type:'mcp-info', name:figma.root.name, fileKey:figma.fileKey || null,
    pageId:figma.currentPage.id, pageName:figma.currentPage.name});
}
figma.on('currentpagechange', reportMcpInfo);
function executeMcpCommand(msg) {
  mcpQueue = mcpQueue.then(async function () {
    if (_exporting) throw new Error('F2A 正在导出，请稍后重试');
    mcpBusy = true;
    mcpCommandId = msg.id;
    figma.ui.postMessage({type:'mcp-busy', busy:true});
    try {
      if (msg.command === 'f2a_export_aep') {
        var o = msg.params || {};
        await exportSelectionSVG(true, !!o.organize, o.ignoreHidden !== false, true, true, o.rasterTexts === true,
          Object.assign({}, o, {target:'aep'}), msg.id);
        return;
      }
      var result = await F2AMCP.execute(msg.command, msg.params || {});
      figma.ui.postMessage({type:'mcp-result', id:msg.id, result:result});
    } finally {
      if (F2AMCP.isWrite(msg.command)) figma.commitUndo();
      mcpBusy = false;
      mcpCommandId = null;
      figma.ui.postMessage({type:'mcp-busy', busy:false});
    }
  }).catch(function (error) {
    figma.ui.postMessage({type:'mcp-result', id:msg.id, error:error.message || String(error), nodeId:error.nodeId || null});
  });
  return mcpQueue;
}

